import { Injectable } from '@angular/core';
import {ToastController, AlertController} from '@ionic/angular'

@Injectable({
  providedIn: 'root'
})
export class ToastService {

  constructor(private toastCtrl:ToastController,private alertCtrl:AlertController) {

   }
    async presentToast(msg:string,color) {      
    const toast =  await this.toastCtrl.create({
      message: msg,
      duration: 2000,
      color:this.getColor(color)
    });
    return await toast.present();
  }
  async presentToastWithOptions(msg) {
    const toast = await this.toastCtrl.create({
      header: 'Toast header',
      message: msg,
      position: 'top',
      buttons: [
        {
          side: 'start',
          icon: 'star',
          text: 'Favorite',
          handler: () => {           
          }
        }, {
          text: 'Done',
          role: 'cancel',
          handler: () => {            
          }
        }
      ]
    });
    return await toast.present();
  }
  async setAlertForUpdateCheck(header,message){
    const alert = await this.alertCtrl.create({
      header: header,
      backdropDismiss:false,
      
      message: message,
      buttons: [
        {
          text: 'Ok',
          role: 'ok',
          cssClass: 'secondary',
          handler: (blah) => {
            alert.dismiss('ok')            
            return false
          }
        }
      ]
    });

    await alert.present()
    let result=await alert.onDidDismiss();
    return result

    }
  async setAlert(title_name,msg){
 

    const alert= await this.alertCtrl.create({
      header:title_name,
      message:msg,
      cssClass:'buttoncss',
      buttons:[{
        text:'No',
        cssClass:'btnNo',
        handler:()=>{
          alert.dismiss(false)
          return false
        }
      },{
        text:'Yes',
        cssClass:'btnYes',
        handler:()=>{
          alert.dismiss('s')
          return false
        }
      },
      ]
    });    
    return alert
    
    }
    async presentAlertConfirm(header,message) {
      const alert = await this.alertCtrl.create({
        header: header,
        message: message,
        buttons: [
          {
            text: 'Cancel',
            role: 'cancel',
            cssClass: 'secondary',
            handler: (blah) => {
              alert.dismiss('cancel')              
              return false
            }
          }, {
            text: 'Okay',
            role: 'okay',
            handler: () => {
              alert.dismiss('okay')              
              return false
            }
          }
        ]
      });
  
      await alert.present()
      let result=await alert.onDidDismiss();
      return result

    }
  getColor(color){
    switch(color){
      case 'success':
        return 'primary'
      case 'warning':
         return 'warning'
      case 'error':
          return 'danger'
      case 'success_green':
          return 'secondary'
      case 'dark':
          return 'dark'  
      default :
          return ''
    }
  }
}
