import { Injectable } from '@angular/core';
import { environment } from 'src/environments/environment';
import { DataService } from '../data.service';

@Injectable({
  providedIn: 'root'
})
export class RegulatoryService {
  private emisApiUrl = environment.emisApiUrl;

  constructor(private dataService: DataService) { }

  toGetRCIndex(data: any) {
    return this.dataService.post(this.emisApiUrl + '/RCSectn', data).map(res => {
        return res;
    });
}

  toGetRCForm(data: any) {
    return this.dataService.post(this.emisApiUrl + '/RCQuestChce', data).map(res => {
        return res;
    });
}

toGetRCFormquestion(data: any) {
  return this.dataService.post(this.emisApiUrl + '/rc_get_questions', data).map(res => {
      return res;
  });
}

toGetAppList() {
  return this.dataService.getData(this.emisApiUrl + '/RCInfoList', true)
}

saveRC(data: any) {
  return this.dataService.post(this.emisApiUrl +'/RCInsert', data).map(res => {
    return res;
});;
}

overallsaveRC(data: any) {
  return this.dataService.post(this.emisApiUrl +'/final_deo_submit', data).map(res => {
    return res;
});;
}

rejectForm(data: any) {
  return this.dataService.post(this.emisApiUrl +'/RCMobStatus', data).map(res => {
    return res;
});;
}

cancelForm(data: any) {
  return this.dataService.post(this.emisApiUrl +'/cancel_application', data).map(res => {
    return res;
});;
}

otpSubmit(data: any) {
  return this.dataService.post(this.emisApiUrl +'/OfclRCOTPVerfictn', data).map(res => {
    return res;
});;
}

otpverifySubmit(data:any) {
  return this.dataService.post(this.emisApiUrl +'/RCOTPValidatn', data).map(res => {
    return res
  });
}

}
