import { Injectable } from '@angular/core';
import { DataService } from 'src/app/services/data.service';
import { environment } from 'src/environments/environment.prod';
// import { environment } from 'src/environments/environment';

@Injectable({
  providedIn: 'root'
})
export class DynamicformService {
  private emisApiUrl = environment.emisApiUrl;
  private emisApiUrl3 = environment.emisApiUrl3;
  
  constructor(private dataService: DataService) { }

  DynmcFrmAnswrSave(data) {
    return this.dataService.post(this.emisApiUrl3 + '/DynmcFrmAnswrSave', data);
  }

  jsonFetch(id){
    return this.dataService.getData(this.emisApiUrl3 + '/JSONfetch?id=' + id, true);
  }

  get_data_set(data){
    return this.dataService.post(this.emisApiUrl3 + '/get_data_set', data);
  }

  // GetOoscOtherDistrict(DistId) {
  //   return this.dataService.getData(this.emisApiUrl + '/OSCstudentsget?DistId=' + DistId, true);
  // }
}
