import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { ModalController, NavParams } from '@ionic/angular';
import { UserService } from 'src/app/services/emis/user.service';
@Component({
  selector: 'app-auto-slot',
  templateUrl: './auto-slot.page.html',
  styleUrls: ['./auto-slot.page.scss'],
})
export class AutoSlotPage implements OnInit {
  schoolClassData:any[];
  school_name: any;
  slot: any;
  school_id: any;
  item: any;
  startdate: any;
  enddate: any;
  statusMode: any;
  cycleNo: any;
  eventenddate: any;
  eventstartdate: any;

  constructor(private modalCtrl:ModalController,private navParams:NavParams,
    private userService: UserService,private router: Router) { 
  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.schoolClassData = this.navParams.get('schoolClassData');
    this.school_name = this.navParams.get('school_name');
    this.slot = this.navParams.get('slot');
    this.school_id = this.navParams.get('school_id');
    this.item = this.navParams.get('item');
    this.startdate = this.navParams.get('startdate');
    this.enddate = this.navParams.get('enddate');
    this.statusMode = this.navParams.get('statusMode');
    this.cycleNo = this.navParams.get('cycle');
    this.eventenddate = this.navParams.get('eventenddate');
    this.eventstartdate = this.navParams.get('eventstartdate');

  }
  closeModal() {
    this.modalCtrl.dismiss();
  }
  onSave() {
    for (let i = 0; i < this.schoolClassData.length; i++) {
      let data1 = {
        "IndexId": "",
        "ProgramType": "3",
        "UserId": this.schoolClassData[i].user_id,
        "SchoolId": this.school_id,
        "PlanningDate": this.schoolClassData[i].planning_date,
        "Session": this.schoolClassData[i].session,
        "CycleId": this.cycleNo,
        "Type": '2'
      }
      let data = {
        "records": data1
      }
      this.userService.slotData(data).subscribe((response) => {
      this.router.navigate(['/tabs/school-schedule'], { queryParams: { "item": this.item, "startdate": this.startdate, "enddate": this.enddate, "eventstartdate": this.eventstartdate, "eventenddate": this.eventenddate,'statusMode': this.statusMode, 'cycle': this.cycleNo} });
      
        this.modalCtrl.dismiss();
      })
    }
  }
}
